import React,{FormEvent,useCallback,useEffect,useRef,useState}from"react";
import{Link}from"react-router-dom";
import{BriefcaseBusiness,Box,ClipboardList,MapPin,Megaphone,Truck}from"lucide-react";
import{Button}from"./Button";import{Input}from"./Input";import{Textarea}from"./Textarea";import{Select,SelectContent,SelectItem,SelectTrigger,SelectValue}from"./Select";import KhedmahPublicShell from"./KhedmahPublicShell";
import{manageKhedmah}from"../endpoints/integrations/khedmah_manage_POST.schema";
import{getKhedmahPublic}from"../endpoints/integrations/khedmah_public_GET.schema";
import styles from"./KhedmahOperations.module.css";
import KhedmahMapPreview from"./KhedmahMapPreview";
import KhedmahCatalogTools from "./KhedmahCatalogTools";
import KhedmahFulfillmentActions from "./KhedmahFulfillmentActions";
import {khedmahManagementAttempts as attempts} from "../helpers/khedmahManagementAttempts";
import type {ManageAction,ManageFailure} from "../endpoints/integrations/khedmah_manage_POST.schema";
import {emitMerchantPlacedAlert,MERCHANT_ALERT_INTERVAL_MS,MERCHANT_FOREGROUND_ALERT_NOTICE,merchantAlertMessage,placedOrderIds} from "../helpers/khedmahMerchantAlerts";
type Mode="business"|"products"|"ads"|"merchant"|"courier";type Row=Record<string,any>;
const merchantCategories=new Set(["restaurant","cafe","bakery","sweets","catering","juice_icecream","butcher","grocery","fruits_vegetables","fish_poultry_shop","pharmacy"]);
const nav:[Mode,string,React.ElementType][]=[["business","أنشطتي",BriefcaseBusiness],["products","منتجاتي",Box],["ads","إعلاناتي",Megaphone],["merchant","طلبات المطعم",ClipboardList],["courier","مهام المندوب",Truck]];
const status:Record<string,string>={draft:"مسودة",pending:"قيد المراجعة",pending_review:"قيد المراجعة",active:"منشور",inactive:"غير نشط",approved:"معتمد",rejected:"مرفوض",placed:"طلب جديد",quoted:"بانتظار العميل",merchant_confirmed:"مؤكد",courier_assigned:"عُيّن مندوب",courier_accepted:"قبله المندوب",ready_for_pickup:"جاهز للاستلام",picked_up:"في الطريق",delivered:"تم التسليم",cancelled:"ملغي"};
export default function KhedmahOperations({mode}:{mode:Mode}){
 const[rows,setRows]=useState<Row[]>([]),[businesses,setBusinesses]=useState<Row[]>([]),[couriers,setCouriers]=useState<Row[]>([]),[selected,setSelected]=useState(""),[loading,setLoading]=useState(true),[loaded,setLoaded]=useState(false),[saving,setSaving]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState(""),[merchantAlert,setMerchantAlert]=useState(""),[authRequired,setAuthRequired]=useState(false),[creationPending,setCreationPending]=useState(false),[refreshRequired,setRefreshRequired]=useState(false),[formVersion,setFormVersion]=useState(0),[actorKey,setActorKey]=useState("");
 const[categories,setCategories]=useState<Row[]>([]),[cities,setCities]=useState<Row[]>([]),[catalogError,setCatalogError]=useState(""),[legacyCreationPending,setLegacyCreationPending]=useState(false);
 const life=useRef(0),lock=useRef(false),readController=useRef<AbortController|null>(null),writeController=useRef<AbortController|null>(null),alive=useRef(true),activeMode=useRef(mode),activeActor=useRef(""),lastMerchantAlert=useRef({signature:"",at:0});
 activeMode.current=mode;
 const creationScope="catalog-create:"+mode+":"+actorKey;
 const denyAccess=useCallback(()=>{life.current++;activeActor.current="";readController.current?.abort();writeController.current?.abort();setActorKey("");setRows([]);setBusinesses([]);setCouriers([]);setLoaded(false);setLoading(false);setCreationPending(false);setNotice("");setFormVersion(v=>v+1);setAuthRequired(true);},[]);
 const loadCatalog=useCallback(async(signal?:AbortSignal)=>{try{const[a,b]=await Promise.all([getKhedmahPublic("categories",signal),getKhedmahPublic("cities",signal)]);if(signal?.aborted||!alive.current)return;setCategories(a.categories||[]);setCities(b.cities||[]);setCatalogError("");}catch{if(!signal?.aborted&&alive.current){setCategories([]);setCities([]);setCatalogError("تعذر تحميل التصنيفات أو المدن. أعد تحميل الخيارات قبل الحفظ.");}}},[]);
 useEffect(()=>{alive.current=true;const c=new AbortController();void loadCatalog(c.signal);return()=>{alive.current=false;life.current++;c.abort();readController.current?.abort();writeController.current?.abort();};},[loadCatalog]);
 const load=useCallback(async()=>{
  const epoch=++life.current;readController.current?.abort();const c=new AbortController();readController.current=c;
  setLoading(true);setLoaded(false);setError("");setRows([]);setBusinesses([]);setCouriers([]);setCreationPending(false);
  try{
   const mine=await manageKhedmah("business.list",{},c.signal);
   if(typeof mine.actorKey!=="string"||!/^[a-f0-9]{64}$/.test(mine.actorKey)||!Array.isArray(mine.businesses))throw new Error("تعذر التحقق من حساب صاحب البيانات. أعد تحميل الصفحة.");
   const owner=mine.actorKey,bs:Row[]=mine.businesses.filter((business:Row)=>mode==="merchant"?merchantCategories.has(business.categoryCode):mode==="courier"?business.categoryCode==="delivery_courier":true),id=bs.some(b=>b.id===selected)?selected:bs[0]?.id||"";let nextRows:Row[]=bs,nextCouriers:Row[]=[];
   if(mode==="products")nextRows=(await manageKhedmah("product.list",{},c.signal)).products;
   if(mode==="ads")nextRows=(await manageKhedmah("ad.list",{},c.signal)).ads;
   if(mode==="merchant"&&id){const[o,courierList]=await Promise.all([manageKhedmah("merchant.orders",{businessId:id},c.signal),manageKhedmah("merchant.couriers",{businessId:id},c.signal)]);nextRows=o.orders;nextCouriers=courierList.couriers;}
   if(mode==="courier"&&id)nextRows=(await manageKhedmah("courier.orders",{businessId:id},c.signal)).orders;
   if((mode==="merchant"||mode==="courier")&&!id)nextRows=[];
   if(mode!=="business"){
    const confirmed=await manageKhedmah("business.list",{},c.signal);
    if(confirmed.actorKey!==owner)throw Object.assign(new Error("تغيّر الحساب أثناء تحميل البيانات. أعد التحميل للحساب الحالي."),{code:"ACTOR_CHANGED"});
   }
   if(epoch!==life.current||c.signal.aborted||!alive.current)return;
   if(activeActor.current&&activeActor.current!==owner){setFormVersion(v=>v+1);setNotice("");}
   activeActor.current=owner;setActorKey(owner);setBusinesses(bs);setRows(nextRows);setCouriers(nextCouriers);setAuthRequired(false);setLoaded(true);setRefreshRequired(false);setCreationPending(!!attempts.read("catalog-create:"+mode+":"+owner));setLegacyCreationPending(!!attempts.read("catalog-create:"+mode));
   if(selected!==id)setSelected(id);
   return owner;
  }catch(e){if(epoch!==life.current||c.signal.aborted||!alive.current)return;const issue=e as ManageFailure;activeActor.current="";setActorKey("");if(issue.status===401||issue.status===403)denyAccess();else setError(issue.message||"تعذر تحميل البيانات.");}
  finally{if(epoch===life.current&&!c.signal.aborted&&alive.current)setLoading(false);}
 },[mode,selected,denyAccess]);
 useEffect(()=>{void load();},[load]);
 useEffect(()=>{
  if(mode!=="merchant"||!loaded){setMerchantAlert("");lastMerchantAlert.current={signature:"",at:0};return;}
  const ids=placedOrderIds(rows),signature=ids.join(":");
  if(!ids.length){setMerchantAlert("");lastMerchantAlert.current={signature:"",at:0};return;}
  const fire=()=>{
   const now=Date.now(),last=lastMerchantAlert.current;
   if(last.signature===signature&&now-last.at<MERCHANT_ALERT_INTERVAL_MS)return;
   lastMerchantAlert.current={signature,at:now};setMerchantAlert(merchantAlertMessage(ids.length));
   const vibrate=typeof navigator!=="undefined"&&typeof navigator.vibrate==="function"?navigator.vibrate.bind(navigator):undefined;
   const notify=typeof Notification!=="undefined"&&Notification.permission==="granted"?(title:string,options?:NotificationOptions)=>{new Notification(title,options);}:undefined;
   emitMerchantPlacedAlert(ids.length,{vibrate,notify});
  };
  fire();const timer=window.setInterval(fire,MERCHANT_ALERT_INTERVAL_MS);return()=>window.clearInterval(timer);
 },[mode,loaded,rows]);
 // Read-only foreground polling complements (but cannot replace) background push.
 // Verify the owner before exposing refreshed orders; never overlap a write or a full reload.
 useEffect(()=>{
  if(mode!=="merchant"||!loaded||!selected||!actorKey||authRequired||refreshRequired)return;
  let stopped=false,inFlight=false;
  const controllers=new Set<AbortController>();
  const poll=async()=>{
   if(stopped||inFlight||lock.current||loading||document.visibilityState==="hidden"||readController.current?.signal.aborted)return;
   inFlight=true;
   const controller=new AbortController();controllers.add(controller);
   const epoch=life.current;
   const current=()=>!stopped&&!controller.signal.aborted&&alive.current&&life.current===epoch&&!lock.current&&activeActor.current===actorKey&&activeMode.current==="merchant";
   try{
    const owner=await manageKhedmah("business.list",{},controller.signal);
    if(!current())return;
    if(owner.actorKey!==actorKey){denyAccess();return;}
    if(!Array.isArray(owner.businesses)||!owner.businesses.some((b:Row)=>b.id===selected&&merchantCategories.has(b.categoryCode))){denyAccess();return;}
    const result=await manageKhedmah("merchant.orders",{businessId:selected},controller.signal);
    if(!current())return;
    if(Array.isArray(result.orders))setRows(result.orders);
   }catch(e){
    if(!current())return;
    const issue=e as ManageFailure;
    if(issue.status===401||issue.status===403)denyAccess();
    // Transient read failures must not erase the last confirmed order list.
   }finally{controllers.delete(controller);inFlight=false;}
  };
  const timer=window.setInterval(()=>void poll(),MERCHANT_ALERT_INTERVAL_MS);
  const onVisible=()=>{if(document.visibilityState==="visible")void poll();};
  document.addEventListener("visibilitychange",onVisible);
  return()=>{stopped=true;window.clearInterval(timer);document.removeEventListener("visibilitychange",onVisible);controllers.forEach(c=>c.abort());};
 },[mode,loaded,selected,actorKey,authRequired,refreshRequired,denyAccess]);
 const isReplayable=(action:ManageAction)=>["business.create","product.create","ad.create","ad.update","ad.submit","ad.deactivate","ad.reactivate","ad.image.upload","ad.image.remove"].includes(action);
 async function refreshActor(){activeActor.current="";setActorKey("");setLoaded(false);setRows([]);setBusinesses([]);setCouriers([]);setCreationPending(false);setFormVersion(v=>v+1);await load();if(alive.current)setNotice("تغيّر الحساب المستخدم. راجع البيانات الجديدة وأدخل تفاصيل العملية للحساب الحالي.");}
 async function act(action:ManageAction,payload:Record<string,unknown>,message:string):Promise<any>{
  if(lock.current||!loaded||authRequired||refreshRequired||!actorKey||activeActor.current!==actorKey)return;
  if(legacyCreationPending&&["business.create","product.create","ad.create"].includes(action))return;
  lock.current=true;setSaving(true);setError("");setNotice("");const modeAtStart=mode,actorAtStart=actorKey,c=new AbortController();writeController.current=c;
  const current=()=>alive.current&&activeMode.current===modeAtStart&&activeActor.current===actorAtStart&&!c.signal.aborted;
  const create=["business.create","product.create","ad.create"].includes(action),scope=create?creationScope:action+":"+actorAtStart+":"+String(payload.id??"")+":"+String(payload.expectedContentRevision??payload.expectedRevision??"");
  const boundPayload=create?{...payload,expectedActorKey:actorAtStart}:payload;
  const inheritedAttempt=isReplayable(action)&&!!attempts.read(scope);
  try{
   const request=isReplayable(action)?{...boundPayload,clientRequestId:(await attempts.begin(scope,action,boundPayload)).clientRequestId}:boundPayload;
   if(!current())return;
   const result=await manageKhedmah(action,request,c.signal);
   if(create&&result.actorKey!==actorAtStart)throw Object.assign(new Error("تعذر تأكيد حساب نتيجة الحفظ. استعد نتيجة المحاولة قبل الإرسال مجددًا."),{outcome:"unknown"});
   if(isReplayable(action))attempts.complete(scope);
   if(!current())return;
   setCreationPending(false);if(create)setFormVersion(v=>v+1);await load();if(!current())return;setNotice(message);return result;
  }catch(e){if(!alive.current||activeMode.current!==modeAtStart||c.signal.aborted)return;const issue=e as ManageFailure;
   if(issue.code==="ACTOR_CHANGED"){await refreshActor();return;}
   if(!inheritedAttempt&&issue.outcome==="not_applied"&&issue.status!==409&&isReplayable(action))attempts.complete(scope);
   if(issue.status===401||issue.status===403)denyAccess();
   else{if(issue.outcome==="unknown"&&!isReplayable(action))setRefreshRequired(true);setCreationPending(create&&!!attempts.read(scope));setError(issue.message||"تعذر حفظ التغيير.");}
  }finally{lock.current=false;if(alive.current&&activeMode.current===modeAtStart)setSaving(false);if(writeController.current===c)writeController.current=null;}
 }
 async function recoverCreation(){
  if(lock.current||!loaded||!actorKey||activeActor.current!==actorKey)return;lock.current=true;setSaving(true);setError("");const modeAtStart=mode,actorAtStart=actorKey,scope=creationScope,c=new AbortController();writeController.current=c;
  const current=()=>alive.current&&activeMode.current===modeAtStart&&activeActor.current===actorAtStart&&!c.signal.aborted;
  try{
   const previous=attempts.read(scope);if(!previous)return;
   const kind=mode==="business"?"business":mode==="products"?"product":"ad",result=await manageKhedmah("creation.resolve",{kind,clientRequestId:previous.clientRequestId,expectedActorKey:actorAtStart},c.signal);
   if(!current())return;
   if(result.actorKey!==actorAtStart)throw new Error("تعذر تأكيد حساب نتيجة المحاولة. أعد تحميل البيانات.");
   if(result.record){attempts.complete(scope);setCreationPending(false);await load();if(!current())return;setNotice("تم العثور على السجل المحفوظ للمحاولة السابقة. أكمل العمل من بطاقته.");}
   else setError("لم يظهر سجل لهذه المحاولة بعد. أعد إرسال البيانات نفسها فقط؛ ستُستخدم المحاولة السابقة دون إنشاء طلب جديد.");
  }catch(e){if(!alive.current||activeMode.current!==modeAtStart||c.signal.aborted)return;const issue=e as ManageFailure;if(issue.code==="ACTOR_CHANGED")await refreshActor();else if(issue.status===401||issue.status===403)denyAccess();else setError(issue.message);}
  finally{lock.current=false;if(alive.current&&activeMode.current===modeAtStart)setSaving(false);if(writeController.current===c)writeController.current=null;}
 }
 async function saveAd(payload:Row,files:File[]):Promise<boolean>{
  const result=await act("ad.create",payload,"تم حفظ الإعلان كمسودة. أضف صوره وأكمل المراجعة من بطاقة الإعلان.");
  if(!result?.ad)return false;
  if(files.length)setNotice("تم حفظ مسودة الإعلان. افتح «الصور والتفاصيل» في بطاقتها لإرفاق الصور قبل الإرسال.");
  return true;
 }
 const title=nav.find(x=>x[0]===mode)?.[1]||"مركز التشغيل";
 if(authRequired)return <KhedmahPublicShell title={title} description="سجّل الدخول للوصول إلى مساحة إدارة أعمالك وطلباتك."><section className={styles.authGate}><h2>يلزم حساب مخوّل للوصول</h2><p>سجّل الدخول بحساب صاحب البيانات ثم أعد فتح الصفحة.</p><Link className={styles.authLink} to={"/platform/account?next="+encodeURIComponent("/platform/"+({business:"manage",products:"products-manage",ads:"ads-manage",merchant:"merchant",courier:"courier"}as Record<Mode,string>)[mode])}>تسجيل الدخول والمتابعة</Link><Link className={styles.backLink} to="/platform">العودة إلى الرئيسية</Link></section></KhedmahPublicShell>;
 return <KhedmahPublicShell title={title} description="إدارة عمليات خدمة من داخل المنصة."><nav className={styles.nav} aria-label="إدارة القسم الحالي">{nav.filter(([m])=>mode==="business"?m==="business":mode==="products"?m==="products"||m==="business":mode==="ads"?m==="ads"||m==="business":mode==="merchant"?m==="merchant"||m==="business":m==="courier"||m==="business").map(([m,label,Icon])=><Link key={m} className={m===mode?styles.active:""} to={"/platform/"+({business:"manage",products:"products-manage",ads:"ads-manage",merchant:"merchant",courier:"courier"}as Record<Mode,string>)[m]}><Icon size={17}/>{label}</Link>)}</nav>
  {error&&<div className={styles.error} role="alert">{error}<Button type="button" variant="outline" disabled={saving||loading} onClick={()=>void load()}>تحديث البيانات</Button></div>}{notice&&<p className={styles.success} role="status">{notice}</p>}{merchantAlert&&<p className={styles.merchantAlert} role="alert">{merchantAlert} افتح الطلب وحدّث الحالة بعد المراجعة.</p>}{mode==="merchant"&&loaded&&<p role="note">{MERCHANT_FOREGROUND_ALERT_NOTICE}</p>}
  {catalogError&&<div className={styles.error} role="alert">{catalogError}<Button type="button" variant="outline" onClick={()=>void loadCatalog()}>إعادة تحميل الخيارات</Button></div>}
  {creationPending&&<div className={styles.error} role="alert"><p>توجد محاولة إنشاء سابقة لم تتأكد نتيجتها. استعد نتيجتها أولًا، أو أعد إرسال البيانات نفسها فقط.</p><Button type="button" variant="outline" disabled={saving} onClick={()=>void recoverCreation()}>استعادة نتيجة المحاولة</Button></div>}
  {legacyCreationPending&&<p role="alert">توجد محاولة إنشاء من جلسة أقدم دون حساب محدد. أوقفنا إنشاء سجل جديد لهذا النوع حتى تُراجع نتيجة تلك المحاولة وحسابها. يمكنك مراجعة السجلات الحالية.</p>}
  {refreshRequired&&<p role="alert">راجع البيانات الحالية قبل تنفيذ إجراء جديد.</p>}
  {loaded&&(mode==="merchant"||mode==="courier")&&<Button type="button" variant="outline" disabled={saving||loading} onClick={()=>void load()}>تحديث الحالة</Button>}
  {loaded&&(mode==="merchant"||mode==="courier")&&!!businesses.length&&<section className={styles.selector}><label>اختر النشاط<Select value={selected||"_none"} disabled={saving||loading||refreshRequired} onValueChange={v=>setSelected(v==="_none"?"":v)}><SelectTrigger aria-label="النشاط الذي تعرض طلباته"><SelectValue placeholder="اختر نشاطًا"/></SelectTrigger><SelectContent><SelectItem value="_none">اختر نشاطًا</SelectItem>{businesses.map(b=><SelectItem key={b.id} value={b.id}>{b.name} · {b.categoryCode}</SelectItem>)}</SelectContent></Select></label></section>}
  {loaded&&!catalogError&&mode==="business"&&<BusinessForm key={"business:"+actorKey+":"+formVersion} categories={categories} cities={cities} busy={saving} blocked={refreshRequired||legacyCreationPending} onSave={p=>void act("business.create",p,"تم إنشاء النشاط. راجع حالة المحتوى والتوثيق في بطاقته.")}/>}
  {loaded&&!catalogError&&mode==="products"&&<ProductForm key={"product:"+actorKey+":"+formVersion} businesses={businesses} categories={categories} busy={saving||refreshRequired||legacyCreationPending} onSave={p=>void act("product.create",p,"تم حفظ المنتج كمسودة. أضف صورة قبل إرساله للمراجعة.")}/>}
  {loaded&&!catalogError&&mode==="ads"&&<AdForm key={"ad:"+actorKey+":"+formVersion} businesses={businesses} categories={categories} cities={cities} busy={saving} blocked={refreshRequired||legacyCreationPending} clearError={()=>setError("")} onSave={saveAd}/>}
  {loading?<p role="status">جارٍ تحميل البيانات…</p>:loaded&&<section className={styles.grid}>{!rows.length?<div className={styles.empty}><h2>{(mode==="merchant"||mode==="courier")&&!businesses.length?"لا يوجد نشاط مناسب لهذه المساحة":"لا توجد بيانات بعد"}</h2><p>{mode==="merchant"?(businesses.length?"لا توجد طلبات لهذا النشاط حاليًا. يمكنك تحديث الحالة أو اختيار نشاط آخر.":"تظهر هنا أنشطتك من فئات المطاعم والأغذية والمتجر الغذائي والصيدلية. راجع تصنيف نشاطك من أنشطتي."):mode==="courier"?(businesses.length?"لا توجد مهام لهذا المندوب حاليًا. حدّث الحالة للاطلاع على المهام الجديدة.":"تحتاج إلى نشاط من فئة مندوب توصيل ضمن أنشطتك لعرض المهام."):"ابدأ من النموذج أعلاه، أو اختر نشاطًا آخر."}</p></div>:rows.map(r=><article key={r.id} className={styles.card}><span>{catalogStatus(mode,r,businesses)}</span><h2>{r.name||r.titleAr||r.merchantName||"طلب خدمة"}</h2>{r.descriptionAr&&<p>{r.descriptionAr}</p>}{r.rejectionReason&&<p role="note">سبب الرفض: {r.rejectionReason}</p>}{r.items?.map((i:Row)=><p key={i.productListingId}>{i.titleAr} × {i.quantity}</p>)}{r.price!=null&&<strong>{Number(r.price).toLocaleString("ar-SY")} {r.currency}</strong>}{r.priceMinor!=null&&<strong>{Number(r.priceMinor).toLocaleString("ar-SY")} {r.currency}</strong>}{r.total!=null&&<strong>{Number(r.total).toLocaleString("ar-SY")} {r.currency}</strong>}{mode==="business"||mode==="products"||mode==="ads"?<KhedmahCatalogTools mode={mode} row={r} categories={categories} cities={cities} businesses={businesses} busy={saving||refreshRequired} act={act} onRefresh={()=>void load()} onAccessDenied={denyAccess}/>:<Actions mode={mode} row={r} couriers={couriers} busy={saving||refreshRequired} act={act}/>}</article>)}</section>}
 </KhedmahPublicShell>;
}
function catalogStatus(mode:Mode,row:Row,businesses:Row[]){
 if(mode==="business")return row.visibility==="public"&&row.moderationStatus==="approved"&&row.trustStatus==="approved"&&row.status==="active"?"منشور ومعتمد":`المحتوى: ${status[row.moderationStatus]||"غير متاح"} · التوثيق: ${status[row.trustStatus]||"غير متاح"}`;
 if(mode==="products"){const b=businesses.find(v=>v.id===row.businessProfileId);return row.status==="active"&&row.moderationStatus==="approved"&&b?.visibility==="public"&&b?.moderationStatus==="approved"&&b?.trustStatus==="approved"&&b?.status==="active"?"منشور":row.moderationStatus==="rejected"?"مرفوض":row.status==="active"?"بانتظار الاعتماد أو أهلية النشاط":status[row.status]||"غير متاح";}
