function getCategoryIcon(code:string,name:string){
 const value=(code+" "+name).toLowerCase();
 if(/food|restaurant|مطعم|طعام|مخبز|حلويات/.test(value))return Utensils;
 if(/home|house|منزل|صيانة|تنظيف|سباكة|كهرباء/.test(value))return Home;
 if(/health|medical|صحة|طبيب|طب|صيدل/.test(value))return HeartPulse;
 if(/education|training|تعليم|تدريب|مدرس|دروس/.test(value))return GraduationCap;
 if(/professional|career|مهنة|مهني|محاسب|محام|استشار/.test(value))return Briefcase;
 if(/beauty|جمال|تجميل|صالون|عناية/.test(value))return Sparkles;
 if(/shop|store|shopping|متجر|تسوق|تجارة/.test(value))return ShoppingBag;
 if(/car|auto|سيارات|سيارة|ميكانيك/.test(value))return CarFront;
 if(/transport|delivery|نقل|تكسي|توصيل/.test(value))return Truck;
 if(/tech|software|تقنية|برمجة|حاسوب/.test(value))return Laptop;
 if(/construct|building|بناء|مقاولات|عقار/.test(value))return Building2;
 if(/event|مناسبات|فعاليات/.test(value))return CalendarDays;
 if(/agri|زراعة|زراعي|مواش/.test(value))return Leaf;
 if(/industry|factory|صناعة|مصانع|صناعي/.test(value))return Factory;
 if(/travel|tour|سياحة|سفر|فندق/.test(value))return Plane;
 return Grid2X2;
}
