export function placedOrderIds(rows: readonly Record<string, unknown>[]): string[] {
  return rows
    .filter(row => row.status === "placed" && typeof row.id === "string" && row.id.length > 0)
    .map(row => String(row.id))
    .sort();
}

export function merchantAlertMessage(count: number): string {
  return count === 1 ? "لديك طلب جديد بانتظار المراجعة." : `لديك ${count} طلبات جديدة بانتظار المراجعة.`;
}

export function emitMerchantPlacedAlert(
  count: number,
  env: MerchantAlertEnvironment = {},
): void {
  if (!Number.isSafeInteger(count) || count < 1) return;
  try { env.vibrate?.([250, 120, 250]); } catch { /* Best-effort only. */ }
  try { env.notify?.("خدمة · طلب جديد", { body: merchantAlertMessage(count), tag: "khedmah-merchant-placed" }); }
  catch { /* Mobile browsers may reject Notification construction. */ }
}

import {emitMerchantPlacedAlert,MERCHANT_ALERT_INTERVAL_MS,MERCHANT_FOREGROUND_ALERT_NOTICE,merchantAlertMessage,placedOrderIds} from "./khedmahMerchantAlerts";

describe("Merchant placed-order alerts",()=>{
  it("selects only placed order ids deterministically",()=>{
    expect(placedOrderIds([{id:"b",status:"placed"},{id:"a",status:"placed"},{id:"x",status:"quoted"},{status:"placed"}])).toEqual(["a","b"]);
    expect(MERCHANT_ALERT_INTERVAL_MS).toBe(30000);
    expect(MERCHANT_FOREGROUND_ALERT_NOTICE).toContain("أثناء فتح صفحة الطلبات");
    expect(MERCHANT_FOREGROUND_ALERT_NOTICE).toContain("لا توجد إشعارات خلفية مفعّلة");
    expect(merchantAlertMessage(1)).toContain("طلب جديد");
    expect(merchantAlertMessage(3)).toContain("3 طلبات");
  });

  it("emits bounded best-effort vibration and notification without surfacing platform errors",()=>{
    const vibrate=jasmine.createSpy("vibrate").and.throwError("unsupported");
    const notify=jasmine.createSpy("notify").and.throwError("blocked");
    expect(()=>emitMerchantPlacedAlert(1,{vibrate,notify})).not.toThrow();
    expect(vibrate).toHaveBeenCalledTimes(1);
