import { validateKhedmahWebConfig, type KhedmahWebConfig } from "./khedmahWebConfig";
import { getKhedmahPreviewHealth } from "../endpoints/integrations/khedmah_preview_health_GET.schema";

export interface PreviewAuth {
  signInWithPopup(provider: unknown): Promise<{ user: { getIdToken(force: boolean): Promise<string> } }>;
  signInWithRedirect(provider: unknown): Promise<void>;
  getRedirectResult(): Promise<{ user: { getIdToken(force: boolean): Promise<string> } } | null>;
  signOut(): Promise<void>;
  setPersistence(value: string): Promise<void>;
}
interface BrowserFirebase {
  SDK_VERSION: string;
  apps: Array<{ name: string; options: KhedmahWebConfig; auth(): PreviewAuth }>;
  initializeApp(config: KhedmahWebConfig, name: string): { options: KhedmahWebConfig; auth(): PreviewAuth };
  auth: {
    GoogleAuthProvider: new () => { setCustomParameters(value: { prompt: string }): void };
    Auth: { Persistence: { NONE: string } };
  };
}
let sdkPromise: Promise<BrowserFirebase> | undefined;
function browserFirebase(): BrowserFirebase | undefined {
  return (window as unknown as { firebase?: BrowserFirebase }).firebase;
}
async function loadFirebase(): Promise<BrowserFirebase> {
  if (!sdkPromise) sdkPromise = (async () => {
    // Pin both official browser bundles to one registry and one SDK version.
    // Floot's npm browser resolver instantiated separate modular registries.
    for (const name of ["firebase-app-compat.js", "firebase-auth-compat.js"]) {
      const existing = browserFirebase();
      if (existing && existing.SDK_VERSION !== "13.0.0") throw new Error("SDK_VERSION_CONFLICT");
      if (name === "firebase-app-compat.js" && existing) continue;
      if (name === "firebase-auth-compat.js" && existing?.auth) continue;
      await new Promise<void>((resolve, reject) => {
        const script = document.createElement("script");
        script.src = "https://www.gstatic.com/firebasejs/13.0.0/" + name;
        script.async = true;
        const timer = setTimeout(() => { script.remove(); reject(new Error("SDK_TIMEOUT")); }, 10000);
        script.onload = () => { clearTimeout(timer); resolve(); };
        script.onerror = () => { clearTimeout(timer); script.remove(); reject(new Error("SDK_LOAD_FAILED")); };
        document.head.appendChild(script);
      });
    }
    const sdk = browserFirebase();
    if (!sdk?.auth || sdk.SDK_VERSION !== "13.0.0") throw new Error("SDK_UNAVAILABLE");
    return sdk;
  })().catch(error => { sdkPromise = undefined; throw error; });
  return sdkPromise;
}
const APP_NAME = "khedmah-preview-acceptance";
export async function preparePreviewAuth(config: KhedmahWebConfig): Promise<PreviewAuth> {
  const verified = validateKhedmahWebConfig(config);
  const sdk = await loadFirebase();
  const app = sdk.apps.find(app => app.name === APP_NAME) ?? sdk.initializeApp(verified, APP_NAME);
  if (JSON.stringify(app.options) !== JSON.stringify(verified)) throw new Error("PREVIEW_CONFIG_CHANGED");
  const auth = app.auth();
  await auth.setPersistence(sdk.auth.Auth.Persistence.NONE);
  return auth;
}

export function acceptedPreviewOrigin(origin: string): boolean {
  return origin === "[REDACTED_PUBLIC_DEPLOYMENT_URL]" ||
    origin === "[REDACTED_PUBLIC_DEPLOYMENT_URL]" ||
    origin === "[REDACTED_PUBLIC_DEPLOYMENT_URL]" ||
    origin === "https://5e271f43-96a6-40de-a634-ec3eae023a49.sandbox.floot.app";
}

export async function assertPreviewBackendReady(): Promise<void> {
  try {
    const health = await getKhedmahPreviewHealth({ cache: "no-store" });
    if (health.connected !== true) throw new Error("PREVIEW_BACKEND_UNAVAILABLE");
  } catch {
    throw new Error("PREVIEW_BACKEND_UNAVAILABLE");
  }
}

const REDIRECT_MARKER = "khedmah-preview-google-redirect-v1";

export function previewGoogleNeedsRedirect(userAgent: string, coarsePointer = false): boolean {
  return /Android|iPhone|iPad|iPod|Mobile/i.test(userAgent) || coarsePointer;
}

export function pendingPreviewGoogleRedirect(): boolean {
  try { return window.sessionStorage.getItem(REDIRECT_MARKER) === "1"; }
  catch { return false; }
}

function clearRedirectMarker(): void {
  try { window.sessionStorage.removeItem(REDIRECT_MARKER); } catch { /* Storage may be disabled. */ }
}

function previewGoogleProvider(): unknown {
  const sdk = browserFirebase();
  if (!sdk?.auth) throw new Error("SDK_UNAVAILABLE");
  const provider = new sdk.auth.GoogleAuthProvider();
  provider.setCustomParameters({ prompt: "select_account" });
  return provider;
}

async function exchangePreviewCredential(
  auth: PreviewAuth,
  credential: { user: { getIdToken(force: boolean): Promise<string> } }
): Promise<void> {
  try {
    const idToken = await credential.user.getIdToken(true);
    const response = await fetch("/_api/integrations/khedmah_google", {
      method: "POST", credentials: "same-origin", cache: "no-store",
      headers: { "Content-Type": "application/json" }, body: JSON.stringify({ idToken })
    });
    if (!response.ok) throw new Error(response.status === 503
      ? "PREVIEW_BACKEND_UNAVAILABLE"
      : response.status >= 500 ? "PREVIEW_LOGIN_UNAVAILABLE" : "PREVIEW_LOGIN_REJECTED");
  } finally {
    // Firebase only provides the ID token; Khedmah owns the confirmed session.
    await auth.signOut().catch(() => undefined);
  }
}

export async function exchangePreviewGoogle(auth: PreviewAuth): Promise<void> {
  let credential: { user: { getIdToken(force: boolean): Promise<string> } };
  try {
    credential = await auth.signInWithPopup(previewGoogleProvider());
  } catch (error) {
    await auth.signOut().catch(() => undefined);
    throw error;
  }
  await exchangePreviewCredential(auth, credential);
}

/** Only redirect on mobile after the auth helper domain is verified as same-origin. */
export async function beginPreviewGoogle(auth: PreviewAuth, redirectDomainVerified = false): Promise<boolean> {
  const mobile = previewGoogleNeedsRedirect(
    window.navigator.userAgent,
    window.matchMedia?.("(pointer: coarse)")?.matches ?? false
  );
  if (!mobile || !redirectDomainVerified) { await exchangePreviewGoogle(auth); return true; }
  try {
    window.sessionStorage.setItem(REDIRECT_MARKER, "1");
  } catch {
    // Without a same-tab return marker the result cannot be consumed safely.
    await exchangePreviewGoogle(auth);
    return true;
  }
  try {
    await auth.signInWithRedirect(previewGoogleProvider());
    return false;
  } catch (error) {
    clearRedirectMarker();
    throw error;
  }
}

let redirectCompletion: Promise<boolean> | undefined;
/** Consumes the one-time redirect result after the browser returns to Account. */
export function finishPreviewGoogleRedirect(auth: PreviewAuth): Promise<boolean> {
  if (!pendingPreviewGoogleRedirect()) return Promise.resolve(false);
  if (!redirectCompletion) {
    const current = (async () => {
      try {
        const credential = await auth.getRedirectResult();
        if (!credential) throw new Error("PREVIEW_LOGIN_REJECTED");
        await exchangePreviewCredential(auth, credential);
        return true;
      } finally {
        clearRedirectMarker();
      }
    })();
    redirectCompletion = current;
    void current.then(
      () => { if (redirectCompletion === current) redirectCompletion = undefined; },
      () => { if (redirectCompletion === current) redirectCompletion = undefined; }
    );
  }
  return redirectCompletion;
}

export function previewLoginErrorMessage(error: unknown): string {
  const code = error && typeof error === "object" && "code" in error ? error.code : "";
  if (code === "auth/popup-blocked") return "منع المتصفح نافذة Google. اسمح بالنوافذ المنبثقة ثم أعد المحاولة.";
  if (code === "auth/popup-closed-by-user") return "أُغلقت نافذة Google قبل اكتمال الدخول.";
  if (code === "auth/unauthorized-continue-uri" || code === "auth/unauthorized-domain") return "عنوان العودة من Google غير معتمد في إعدادات Firebase الخاصة بخدمة.";
  if (code === "auth/network-request-failed") return "تعذر الاتصال بخدمة Google. تحقق من الإنترنت ثم أعد المحاولة.";
  if (error instanceof Error && error.message === "PREVIEW_BACKEND_UNAVAILABLE")
    return "خادم خدمة غير متاح حاليًا. تعذر إكمال الدخول؛ لا حاجة لتكرار اختيار حساب Google الآن.";
  if (error instanceof Error && error.message === "PREVIEW_LOGIN_UNAVAILABLE")
    return "تعذر تأكيد الدخول لدى خادم خدمة. حاول مرة أخرى بعد قليل.";
  return "لم يكتمل تأكيد تسجيل الدخول. افحص الجلسة، ثم أعد المحاولة إذا بقيت غير مسجل.";
}
export interface PreviewUser {
  id: string; email: string; status: string;
  profile: { displayName: string; locale: string };
}
export async function readPreviewSession(): Promise<PreviewUser | null> {
  const r = await fetch("/_api/integrations/khedmah_session", {
    credentials: "same-origin", cache: "no-store"
  });
  if (r.status === 401) return null;
  if (!r.ok) throw new Error("SESSION_UNAVAILABLE");
  let payload: unknown;
  try { payload = await r.json(); } catch { throw new Error("SESSION_UNAVAILABLE"); }
  if (!payload || typeof payload !== "object" || Array.isArray(payload) ||
      !("user" in payload) || !payload.user || typeof payload.user !== "object" ||
      Array.isArray(payload.user)) throw new Error("SESSION_UNAVAILABLE");
  const user = payload.user as Record<string, unknown>;
  if (!user.profile || typeof user.profile !== "object" || Array.isArray(user.profile))
    throw new Error("SESSION_UNAVAILABLE");
  const profile = user.profile as Record<string, unknown>;
  if (typeof user.id !== "string" || typeof user.email !== "string" ||
      typeof user.status !== "string" || typeof profile.displayName !== "string" ||
      typeof profile.locale !== "string") throw new Error("SESSION_UNAVAILABLE");
  // Retain only the public fields in the verified session contract.
  return { id: user.id, email: user.email, status: user.status,
    profile: { displayName: profile.displayName, locale: profile.locale } };
}
export async function endPreviewSession(): Promise<void> {
  const r = await fetch("/_api/integrations/khedmah_logout", {
    method: "POST", credentials: "same-origin", cache: "no-store"
  });
  if (!r.ok) throw new Error("LOGOUT_NOT_CONFIRMED");
  if (await readPreviewSession() !== null) throw new Error("LOGOUT_NOT_CONFIRMED");
}

