    const holder = window as unknown as { firebase?: unknown; matchMedia?: (query: string) => { matches: boolean } };
    const previousFirebase = holder.firebase;
    const previousMatchMedia = holder.matchMedia;
    class FakeGoogleProvider { setCustomParameters(_value: { prompt: string }): void {} }
    holder.firebase = { auth: { GoogleAuthProvider: FakeGoogleProvider } };
    holder.matchMedia = () => ({ matches: true });
    const auth = {
      signInWithPopup: jasmine.createSpy("popup"),
      signInWithRedirect: jasmine.createSpy("redirect").and.resolveTo(),
      getRedirectResult: jasmine.createSpy("result").and.resolveTo({ user: { getIdToken: async () => "fake-id-token" } }),
      signOut: jasmine.createSpy("signOut").and.resolveTo(),
      setPersistence: jasmine.createSpy("setPersistence").and.resolveTo(),
    } as unknown as PreviewAuth;
    try {
      expect(await beginPreviewGoogle(auth, true)).toBeFalse();
      expect(pendingPreviewGoogleRedirect()).toBeTrue();
      expect(auth.signInWithPopup).not.toHaveBeenCalled();
      const fetcher = spyOn(globalThis, "fetch").and.resolveTo(new Response("{}", { status: 200 }));
      expect(await finishPreviewGoogleRedirect(auth)).toBeTrue();
      expect(pendingPreviewGoogleRedirect()).toBeFalse();
      expect(fetcher).toHaveBeenCalledTimes(1);
      expect(fetcher.calls.mostRecent().args[0]).toBe("/_api/integrations/khedmah_google");
      expect(JSON.parse(String(fetcher.calls.mostRecent().args[1]?.body))).toEqual({ idToken: "fake-id-token" });
      expect(auth.signOut).toHaveBeenCalled();
