      (auth.signInWithPopup as jasmine.Spy).and.resolveTo({ user: { getIdToken: async () => "fake-id-token" } });
      expect(await beginPreviewGoogle(auth)).toBeTrue();
      expect(auth.signInWithPopup).toHaveBeenCalledTimes(1);
      expect(auth.signInWithRedirect).toHaveBeenCalledTimes(1);
      expect(fetcher).toHaveBeenCalledTimes(2);
      expect(pendingPreviewGoogleRedirect()).toBeFalse();
    } finally {
      holder.firebase = previousFirebase;
      holder.matchMedia = previousMatchMedia;
      window.sessionStorage.removeItem("khedmah-preview-google-redirect-v1");
    }
  });
