    expect(acceptedPreviewOrigin("[REDACTED_PUBLIC_DEPLOYMENT_URL]")).toBeTrue();
    expect(acceptedPreviewOrigin("https://5e271f43-96a6-40de-a634-ec3eae023a49.sandbox.floot.app")).toBeTrue();
    expect(acceptedPreviewOrigin("https://5e271f43-96a6-40de-a634-ec3eae023a49.sandbox.floot.app.evil.example")).toBeFalse();
