  });
  it("requires the complete server session contract without trusting extra response fields", async () => {
    const valid = { id: "u-123", email: "user@example.test", status: "active",
      profile: { displayName: "Verified User", locale: "ar" } };
    const fetcher = spyOn(globalThis, "fetch");
    for (const user of [
      { ...valid, id: undefined },
      { ...valid, status: undefined },
      { ...valid, profile: { ...valid.profile, locale: undefined } },
      { ...valid, profile: { ...valid.profile, displayName: 5 } },
      { ...valid, profile: null },
    ]) {
      fetcher.and.resolveTo(new Response(JSON.stringify({ user }), { status: 200 }));
      await expectAsync(readPreviewSession()).toBeRejectedWithError("SESSION_UNAVAILABLE");
    }
    fetcher.and.resolveTo(new Response(JSON.stringify({ user: { ...valid, secret: "must-not-leak",
      profile: { ...valid.profile, privateNote: "must-not-leak" } } }), { status: 200 }));
    expect(await readPreviewSession()).toEqual(valid);
  });
  it("normalizes invalid JSON and upstream failures without exposing response details", async () => {
    const fetcher = spyOn(globalThis, "fetch").and.resolveTo(new Response("{bad", { status: 200 }));
