    await expectAsync(readPreviewSession()).toBeRejectedWithError("SESSION_UNAVAILABLE");
  });
  it("rejects malformed successful session replies", async () => {
    spyOn(globalThis, "fetch").and.resolveTo(new Response('{"user":{"email":"inert"}}', { status: 200 }));
    await expectAsync(readPreviewSession()).toBeRejectedWithError("SESSION_UNAVAILABLE");
  });
});

