import superjson from "superjson";
import { db } from "../../helpers/db";
import { matchingKhedmaReview, tenderReviewColumns } from "../../helpers/businessTenderReview";
import type { OutputType } from "./tender_GET.schema";
import {safePublicText} from "../../helpers/safePublicDisclosure";
const headers = { "Content-Type": "application/json", "Cache-Control": "no-store" };
export async function handle(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const slug = url.searchParams.get("slug");
    const locale = url.searchParams.get("locale");
    if (!slug) return new Response(superjson.stringify({ error: "معرّف المناقصة مطلوب" }), { status: 400, headers });
    const now = new Date();
    const x = await db.selectFrom("businessTenders").select(tenderReviewColumns).where("publicSlug", "=", slug).where("publicationStatus", "=", "published").where("closingDate", ">", now).executeTakeFirst();
    if (!x) return new Response(superjson.stringify({ error: "المناقصة غير متاحة" }), { status: 404, headers });
    if (x.verificationLevel === "khedma_reviewed") {
      const linked = await db.selectFrom("discoveryItems").select("aiPayload").where("linkedTenderId", "=", x.id).execute();
      if (!matchingKhedmaReview(x, linked.map(item => item.aiPayload), now)) return new Response(superjson.stringify({ error: "المناقصة غير متاحة" }), { status: 404, headers });
    }
    const translation = locale && locale !== "ar" ? await db.selectFrom("businessTenderTranslations").selectAll().where("tenderId","=",x.id).where("locale","=",locale).where("translationStatus","=","published").executeTakeFirst() : undefined;
    const trustRow = locale ? await db.selectFrom("businessTenderTrustAssessments").select(["score","level","reasons","redFlags"]).where("tenderId","=",x.id).orderBy("createdAt","desc").executeTakeFirst() : undefined;
    const output: OutputType = {
      slug:x.publicSlug!,referenceNumber:x.referenceNumber,title:safePublicText(translation?.title||x.title)??"",issuingEntity:safePublicText(x.issuingEntity),sector:safePublicText(x.sector),location:safePublicText(x.location),closingDate:x.closingDate,deadlineRaw:x.deadlineRaw,
      submissionMethod:safePublicText(translation?.submissionMethod||x.submissionMethod),eligibility:safePublicText(translation?.eligibility||x.eligibility),technicalRequirements:safePublicText(x.technicalRequirements),financialRequirements:safePublicText(x.financialRequirements),
      requiredDocuments:safePublicText(translation?.requiredDocuments||x.requiredDocuments),verificationLevel:x.verificationLevel,
      isTranslation:Boolean(translation),translationLocale:translation?.locale||null,
      trust:trustRow?{score:trustRow.score,level:trustRow.level}:null
    };
    return new Response(superjson.stringify(output), { headers });
  } catch { return new Response(superjson.stringify({ error: "تعذر تحميل المناقصة" }), { status: 500, headers }); }
}

import superjson from "superjson";
import { db } from "../../helpers/db";
import { matchingKhedmaReview, tenderReviewColumns } from "../../helpers/businessTenderReview";
import type { OutputType } from "./tenders_GET.schema";
import {safePublicText} from "../../helpers/safePublicDisclosure";
const headers = { "Content-Type": "application/json", "Cache-Control": "no-store" };
export async function handle(): Promise<Response> {
  try {
    const now = new Date();
    const rows = await db.selectFrom("businessTenders").select(tenderReviewColumns).where("publicationStatus", "=", "published").where("publicSlug", "is not", null).where("closingDate", ">", now).orderBy("closingDate", "asc").execute();
    const reviewedIds = rows.filter(x => x.verificationLevel === "khedma_reviewed").map(x => String(x.id));
    const linked = reviewedIds.length ? await db.selectFrom("discoveryItems").select(["linkedTenderId", "aiPayload"]).where("linkedTenderId", "in", reviewedIds).execute() : [];
    const byTender = new Map<string, unknown[]>();
    for (const item of linked) { const key = String(item.linkedTenderId); byTender.set(key, [...(byTender.get(key) || []), item.aiPayload]); }
    const output: OutputType = rows.filter(x => x.verificationLevel !== "khedma_reviewed" || Boolean(matchingKhedmaReview(x, byTender.get(String(x.id)) || [], now))).map(x => ({ slug: x.publicSlug!, referenceNumber: x.referenceNumber, title: safePublicText(x.title)??"", issuingEntity: safePublicText(x.issuingEntity), sector: safePublicText(x.sector), location: safePublicText(x.location), closingDate: x.closingDate, deadlineRaw: x.deadlineRaw, verificationLevel: x.verificationLevel }));
    return new Response(superjson.stringify(output), { headers });
  } catch { return new Response(superjson.stringify({ error: "تعذر تحميل المناقصات" }), { status: 500, headers }); }
}

